package workstore

var schemaKnowledge = []string{
	`CREATE TABLE sharing_grants (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.source_scope_id')) STORED NOT NULL REFERENCES scopes(id))`,
	`CREATE TABLE content (id TEXT PRIMARY KEY NOT NULL,scope_id TEXT NOT NULL REFERENCES scopes(id),media_type TEXT NOT NULL,sha256 TEXT NOT NULL,data BLOB NOT NULL,created_at TEXT NOT NULL)`,
	`CREATE INDEX content_scope ON content(scope_id,id)`,
	`CREATE TABLE memories (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.storage_scope_id')) STORED NOT NULL REFERENCES scopes(id),
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL,
 content_ref TEXT GENERATED ALWAYS AS (json_extract(payload,'$.content_ref')) STORED NOT NULL REFERENCES content(id))`,
	`CREATE INDEX memories_scope_state ON memories(scope_id,state)`,
	`CREATE TABLE trusted_practices (practice_key TEXT PRIMARY KEY NOT NULL,content_hash TEXT NOT NULL)`,
	`CREATE TABLE practices (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.storage_scope_id')) STORED NOT NULL REFERENCES scopes(id),
 owner_key TEXT GENERATED ALWAYS AS (json_extract(payload,'$.owner')) STORED NOT NULL,
 practice_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.id')) STORED NOT NULL,
 version TEXT GENERATED ALWAYS AS (json_extract(payload,'$.version')) STORED NOT NULL,
 content_ref TEXT GENERATED ALWAYS AS (json_extract(payload,'$.content_ref')) STORED NOT NULL REFERENCES content(id),
 UNIQUE(owner_key,practice_id,version))`,
	`CREATE TABLE practice_adoptions (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id))`,
	`CREATE TABLE resources (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 connector_identity TEXT GENERATED ALWAYS AS (json_extract(payload,'$.connector_identity')) STORED NOT NULL,
 source_identity TEXT GENERATED ALWAYS AS (json_extract(payload,'$.source_identity')) STORED NOT NULL,
 UNIQUE(scope_id,connector_identity,source_identity))`,
	`CREATE TABLE resource_collections (resource_id TEXT NOT NULL REFERENCES resources(id),collection_id TEXT NOT NULL,PRIMARY KEY(resource_id,collection_id))`,
	`CREATE TABLE resource_versions (id TEXT PRIMARY KEY NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),
 resource_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.resource_id')) STORED NOT NULL REFERENCES resources(id),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id))`,
	`CREATE TABLE deliveries (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 source_attempt_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.source_attempt_id')) STORED NOT NULL REFERENCES attempts(id),
 outbox_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.notification_outbox_id')) STORED NOT NULL REFERENCES outbox(id))`,
	`CREATE TABLE decision_requests (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL)`,
	`CREATE INDEX decisions_pending ON decision_requests(scope_id,state)`,
	`CREATE TABLE decisions (id TEXT PRIMARY KEY NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),
 request_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.request_id')) STORED NOT NULL REFERENCES decision_requests(id),
 request_revision INTEGER GENERATED ALWAYS AS (json_extract(payload,'$.request_revision')) STORED NOT NULL,
 UNIQUE(request_id,request_revision))`,
	`CREATE TABLE agreements (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id))`,
	`CREATE TABLE agreement_versions (agreement_id TEXT NOT NULL REFERENCES agreements(id),revision INTEGER NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(agreement_id,revision))`,
	`CREATE TABLE quiescence_receipts (attempt_id TEXT PRIMARY KEY NOT NULL REFERENCES attempts(id),payload TEXT NOT NULL CHECK(json_valid(payload)))`,
}
